    height: 477px !important;
    padding-top: 383px !important;
  }
  .cont-redim2 {
    height: 477px !important;
    padding-top: 383px !important;
  }
  .custom-popup2 {
    width: 370px !important;
  }
  ::v-deep .van-sticky--fixed {
    top: 110px !important;
